    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const inv = r.value;

  const r2 = removeLine(inv, 'DES-HOUR');
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.lines.length, 1);
  assert.equal(inv2.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = removeLine(inv, 'NOPE');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = removeLine(inv, 'DES-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT if status is not draft', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const r = removeLine(inv, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine and removeLine do not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const originalLength = inv.lines.length;

  addLine(inv, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(inv.lines.length, originalLength);

  removeLine(inv, 'DES-HOUR');
  assert.equal(inv.lines.length, originalLength);
});

test('issueInvoice issues a draft invoice with a number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = issueInvoice(inv, []);
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.status, 'issued');
  assert.equal(inv2.number, 'INV-2026-0001');
});

test('issueInvoice assigns the next number in sequence', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const existing = ['INV-2026-0001', 'INV-2026-0005'];
  const r2 = issueInvoice(inv, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0006');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoice', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  const r = issueInvoice(inv, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const originalStatus = inv.status;

  issueInvoice(inv, []);
  assert.equal(inv.status, originalStatus);
  assert.equal(inv.number, undefined);
});

